import React from 'react'
import BeliefImg from "../../assets/belieff.png";

const Interest = () => {
  return (
    <section className="interest section" id="interest">
      <div className="interest-container container grid">
        <span className="section-subtitle-sub">
          My Professional Thrills
        </span>
        <h2 className="section-title-sub"> Work Interests</h2>
      </div>
    </section>
  )
}

export default Interest
